;; Generated by LawSpec. Do not edit.
(ns lawspec.build
  "Compiles the Java model with the JDK's compiler: java/src into
  target/classes and java/test into target/test-classes, when a source is
  newer than the last compilation. Both are on the classpath deps.edn gives."
  (:require [clojure.java.io :as io]
            [clojure.string :as str])
  (:import (java.net URL URLClassLoader)
           (javax.tools ToolProvider)))

(defn- sources [root]
  (let [dir (io/file root)]
    (if (.isDirectory dir)
      (->> (file-seq dir) (filter #(str/ends-with? (.getName ^java.io.File %) ".java")) (sort-by str) vec)
      [])))

(defn- stale? [files stamp]
  (let [stamp (io/file stamp)]
    (or (not (.exists stamp))
        (some #(> (.lastModified ^java.io.File %) (.lastModified stamp)) files))))

(defn- javac!
  "Compiles a tree when it is stale, or when forced; true when it did."
  [root out force?]
  (let [files (sources root)
        stamp (str out ".stamp")]
    (when (and (seq files) (or force? (stale? files stamp)))
      (.mkdirs (io/file out))
      (let [compiler (or (ToolProvider/getSystemJavaCompiler)
                         (throw (ex-info "LawSpec needs a JDK: no Java compiler is available" {})))
            arguments (into ["-d" out "-cp" (System/getProperty "java.class.path")
                             "-encoding" "UTF-8" "-proc:none" "-nowarn" "-Xlint:none"]
                            (map str files))
            status (.run compiler nil nil nil (into-array String arguments))]
        (when-not (zero? status)
          (throw (ex-info (str "javac failed on " root) {:root root})))
        (spit stamp "")
        true))))

(defn compile-java!
  "Compiles the model, and with tests? its law cases and test support."
  ([] (compile-java! true))
  ([tests?]
   (let [model? (javac! "java/src" "target/classes" false)]
     (when tests? (javac! "java/test" "target/test-classes" model?)))))

(defn use-classes!
  "Makes the compiled model (and with tests? the law cases) loadable by this
  thread and the code it loads: a JVM started before the first compilation
  has no class directories on its classpath yet."
  ([] (use-classes! true))
  ([tests?]
   (let [dirs (cond-> ["target/classes"] tests? (conj "target/test-classes"))
         urls (into-array URL (map #(.toURL (.toURI (io/file (str % "/")))) dirs))
         thread (Thread/currentThread)]
     (.setContextClassLoader thread (URLClassLoader. urls (.getContextClassLoader thread))))))

(defn -main [& _]
  (compile-java! false)
  (shutdown-agents))
